   365  /* _libssh2_base64_decode
   366   *
   367   * Decode a base64 chunk and store it into a newly alloc'd buffer
   368   */
   369  int _libssh2_base64_decode(LIBSSH2_SESSION *session,
   370                             char **data, size_t *datalen,
   371                             const char *src, size_t src_len)
   372  {
   373      unsigned char *d;
   374      const char *s;
   375      short v;
   376      ssize_t i = 0, len = 0;
   377
   378      *data = LIBSSH2_ALLOC(session, ((src_len / 4) * 3) + 1);
   379      d = (unsigned char *) *data;
   380      if(!d) {
   381          return _libssh2_error(session, LIBSSH2_ERROR_ALLOC,
   382                                "Unable to allocate memory for base64 decoding");
   383      }
   384
   385      for(s = src; s < (src + src_len); s++) {
   386          v = base64_reverse_table[(unsigned char)*s];
   387          if(v < 0)
   388              continue;
   389          switch(i % 4) {
   390          case 0:
   391              d[len] = (unsigned char)(v << 2);
   392              break;
   393          case 1:
   394              d[len++] |= (unsigned char)(v >> 4);
   395              d[len] = (unsigned char)(v << 4);
   396              break;
   397          case 2:
   398              d[len++] |= (unsigned char)(v >> 2);
   399              d[len] = (unsigned char)(v << 6);
   400              break;
   401          case 3:
   402              d[len++] |= (unsigned char)v;
   403              break;
   404          }
   405          i++;
   406      }
   407      if((i % 4) == 1) {
   408          /* Invalid -- We have a byte which belongs exclusively to a partial
   409             octet */
   410          LIBSSH2_FREE(session, *data);
   411          *data = NULL;
   412          return _libssh2_error(session, LIBSSH2_ERROR_INVAL, "Invalid base64");
   413      }
   414
   415      *datalen = len;
   416      return 0;
   417  }
